mapper.update:
UPDATE ai_skill_package_version
SET status = #{status},
    snapshot_json = COALESCE(#{snapshot}, snapshot_json),
    update_by = #{actor},
    update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND package_hash = #{hash}
  AND status = #{expected}
  AND del_flag = 0

UPDATE ai_agent_skill_package
SET del_flag = id,
    update_by = #{actor},
    update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND agent_id = #{agentId}
  AND package_id = #{packageId}
  AND del_flag = 0

UPDATE ai_agent_skill_package
SET del_flag = id,
    update_by = #{actor},
    update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND agent_id = #{agentId}
  AND version_id = #{versionId}
  AND del_flag = 0
